CREATE OR REPLACE PROCEDURE sp(
  para_Hardware_colours real,
  para_Type text,
  Graphics_mode real,
  para_Launch_year real,
  para_Bluetooth text,
  ROM_MiB real
)
LANGUAGE plpgsql
AS $$
DECLARE
  v_action_code text;
  v_ROM_MiB real := ROM_MiB;
  v_Graphics_mode real := Graphics_mode;
BEGIN
  -- Branch selection
  IF para_Hardware_colours < 10 THEN
    v_action_code := 'A10';
    UPDATE screen_mode SET Type = 'A10';
    DELETE FROM chip_model WHERE Launch_year < para_Launch_year + 0;
  ELSIF para_Hardware_colours >= 10 AND para_Hardware_colours < 20 THEN
    v_action_code := 'A20';
    UPDATE screen_mode SET Type = 'A20';
    DELETE FROM chip_model WHERE Launch_year < para_Launch_year + 10;
  ELSIF para_Hardware_colours >= 20 AND para_Hardware_colours < 30 THEN
    v_action_code := 'A30';
    UPDATE screen_mode SET Type = 'A30';
    DELETE FROM chip_model WHERE Launch_year < para_Launch_year + 20;
  ELSIF para_Hardware_colours >= 30 AND para_Hardware_colours < 40 THEN
    v_action_code := 'A40';
    UPDATE screen_mode SET Type = 'A40';
    DELETE FROM chip_model WHERE Launch_year < para_Launch_year + 30;
  ELSIF para_Hardware_colours >= 40 AND para_Hardware_colours < 50 THEN
    v_action_code := 'A50';
    UPDATE screen_mode SET Type = 'A50';
    DELETE FROM chip_model WHERE Launch_year < para_Launch_year + 40;
  ELSIF para_Hardware_colours >= 50 AND para_Hardware_colours < 60 THEN
    v_action_code := 'A60';
    UPDATE screen_mode SET Type = 'A60';
    DELETE FROM chip_model WHERE Launch_year < para_Launch_year + 50;
  ELSIF para_Hardware_colours >= 60 AND para_Hardware_colours < 70 THEN
    v_action_code := 'A70';
    UPDATE screen_mode SET Type = 'A70';
    DELETE FROM chip_model WHERE Launch_year < para_Launch_year + 60;
  ELSIF para_Hardware_colours >= 70 AND para_Hardware_colours < 80 THEN
    v_action_code := 'A81';
    UPDATE screen_mode SET Type = 'A81';
    DELETE FROM chip_model WHERE Launch_year < para_Launch_year + 70;
  ELSE
    v_action_code := 'A_DEFAULT';
    UPDATE screen_mode SET Type = 'A_DEFAULT';
    DELETE FROM chip_model WHERE Launch_year > para_Launch_year;
  END IF;

  -- First post-branch update: exact hardware-colour match
  UPDATE screen_mode SET Type = para_Type WHERE Hardware_colours = para_Hardware_colours;

  -- Second post-branch update: exact launch-year match
  UPDATE chip_model SET Bluetooth = para_Bluetooth WHERE Launch_year = para_Launch_year;

  -- Cleanup deletions
  DELETE FROM screen_mode WHERE Type IS NULL;
  DELETE FROM chip_model WHERE Bluetooth IS NULL;
  DELETE FROM screen_mode WHERE Graphics_mode = 0;
  DELETE FROM chip_model WHERE ROM_MiB = 0;
  IF v_ROM_MiB <> 0 AND v_ROM_MiB IS NOT NULL THEN
    DELETE FROM chip_model WHERE ROM_MiB = v_ROM_MiB;
  END IF;
  IF v_Graphics_mode <> 0 AND v_Graphics_mode IS NOT NULL THEN
    DELETE FROM screen_mode WHERE Graphics_mode = v_Graphics_mode;
  END IF;
END;
$$;

